/* Ana sayfa ile hesaplama merkezi için ortak hesap tanımları. */
const ortakModeller={
  'Boya':{waste:3,extras:[['Kat sayısı','number',2],['Boya tipi','select','Silikonlu|Silikat|Elastik']],items:[['Astar','litre',.12,145,'Malzeme'],['İç cephe boya','litre',.28,285,'Malzeme'],['Boya işçiliği','m²',1,135,'İşçilik'],['Koruma / temizlik','götürü',1,1200,'Diğer']]},
  'Seramik':{waste:10,extras:[['Seramik ebatı','select','30×60 cm|60×60 cm|60×120 cm'],['Derz genişliği','number',3]],items:[['Seramik kaplama','m²',1,650,'Malzeme'],['Yapıştırıcı','25 kg torba',.20,310,'Malzeme'],['Derz dolgu','kg',.35,180,'Malzeme'],['Seramik işçiliği','m²',1,350,'İşçilik'],['Nakliye / zayiat','götürü',1,2500,'Diğer']]},
  'Mantolama':{waste:5,extras:[['Yalıtım sistemi','select','EPS|Taş yünü|XPS'],['Levha kalınlığı','select','5 cm|8 cm|10 cm']],items:[['Yalıtım levhası','m²',1,680,'Malzeme'],['Yapıştırıcı','25 kg torba',.17,320,'Malzeme'],['Dübel','adet',6,4.8,'Malzeme'],['Sıva filesi','m²',1.1,45,'Malzeme'],['Mantolama işçiliği','m²',1,310,'İşçilik'],['İskele / nakliye','götürü',1,4500,'Diğer']]},
  'Çatı':{waste:12,extras:[['Çatı eğimi','number',25],['Kaplama sistemi','select','Kiremit|Metal panel|Shingle']],items:[['Çatı kaplama','m²',1,1250,'Malzeme'],['Su yalıtım örtüsü','m²',1.1,180,'Malzeme'],['Mahya elemanı','mtül',.15,210,'Malzeme'],['Çatı işçiliği','m²',1,410,'İşçilik']]},
  'Parke':{waste:8,extras:[['Paket m²','number',2.4],['Parke sınıfı','select','AC3|AC4|Lamine']],items:[['Laminat parke','m²',1,720,'Malzeme'],['Alt şilte','m²',1,62,'Malzeme'],['Süpürgelik','mtül',.42,135,'Malzeme'],['Parke işçiliği','m²',1,220,'İşçilik']]}
};
Object.assign(ortakModeller,{
  'Ev Tadilatı':{waste:5,extras:[['Yapı türü','select','Daire|Villa|Ofis|Dükkan'],['Oda sayısı','number',3]],items:[['Kırım ve moloz','m²',1,210,'Diğer'],['Genel tadilat malzemesi','m²',1,1850,'Malzeme'],['Uygulama işçiliği','m²',1,1250,'İşçilik']]},
  'Alçı & Sıva':{waste:7,extras:[['Uygulama tipi','select','Saten alçı|Makine sıvası|Kaba sıva'],['Kat sayısı','number',2]],items:[['Sıva harcı','25 kg torba',.42,165,'Malzeme'],['Saten alçı','25 kg torba',.20,230,'Malzeme'],['Köşe profili','mtül',.32,38,'Malzeme'],['Sıva / alçı işçiliği','m²',1,260,'İşçilik']]},
  'Tuğla & Duvar':{waste:5,extras:[['Tuğla tipi','select','13,5 cm|19 cm|Gazbeton'],['Duvar yüksekliği','number',2.8]],items:[['Tuğla','adet',13.5,19,'Malzeme'],['Duvar harcı','25 kg torba',.18,155,'Malzeme'],['Duvar işçiliği','m²',1,310,'İşçilik']]},
  'Beton & Demir':{waste:3,extras:[['Beton sınıfı','select','C25/30|C30/37|C35/45'],['Demir oranı kg/m³','number',110]],items:[['Hazır beton','m³',1,3150,'Malzeme'],['Donatı çeliği','kg',110,36,'Malzeme'],['Kalıp ve işçilik','m³',1,1650,'İşçilik']]},
  'Elektrik':{waste:4,extras:[['Mahal tipi','select','Daire|Ofis|Dükkan'],['Hat uzunluğu','number',4]],items:[['Priz / anahtar seti','adet',1,280,'Malzeme'],['Kablo ve boru','mtül',4,48,'Malzeme'],['Elektrik işçiliği','adet',1,450,'İşçilik']]},
  'Tesisat':{waste:5,extras:[['Tesisat türü','select','Temiz su|Pis su|Karma'],['Çap','select','20 mm|25 mm|32 mm']],items:[['PPRC boru ve fittings','mtül',1,190,'Malzeme'],['Atık su borusu','mtül',.7,165,'Malzeme'],['Tesisat işçiliği','mtül',1,260,'İşçilik']]},
  'Diğer Hesaplar':{waste:5,extras:[['İmalat adı','text','Özel imalat'],['Ölçü birimi','select','m²|mtül|adet|m³']],items:[['Seçilen imalat malzemesi','m²',1,500,'Malzeme'],['Seçilen imalat işçiliği','m²',1,250,'İşçilik']]}
});
function ortakModel(tool){const m=ortakModeller[tool[0]];return m||{waste:5,extras:[['Uygulama tipi','select','Standart|Ekonomik|Premium'],['Proje notu','text','Yeni imalat']],items:[[` ${tool[0]} malzemesi`.trim(),tool[2],1,tool[3],'Malzeme'],[` ${tool[0]} işçiliği`.trim(),tool[2],1,tool[4],'İşçilik'],['Nakliye / sarf','götürü',1,tool[3]*.05,'Diğer']]};}

/* Katalog sayfası bağımsız kalır; ancak ortak modeller ana sayfadaki kalem ve varsayımları kullanır. */
const anaSayfaAraclari=[['Ev Tadilatı','Planlama','m²',1850,1250,'Birden çok işi tek bütçede planlayın.'],['Alçı & Sıva','Duvar','m²',260,260,'Harç, alçı, profil ve uygulama.'],['Tuğla & Duvar','Duvar','m²',310,310,'Tuğla adedi, harç ve işçilik.'],['Beton & Demir','Betonarme','m³',3150,1650,'Beton hacmi, donatı ve kalıp.'],['Elektrik','Elektrik','adet',280,450,'Priz, kablo, boru ve montaj.'],['Tesisat','Mekanik','mtül',190,260,'Boru, bağlantı parçaları ve işçilik.'],['Diğer Hesaplar','Diğer','m²',500,250,'Özel imalatlar için başlangıç hesabı.']];anaSayfaAraclari.reverse().forEach(x=>{if(!tools.some(t=>t[0]===x[0]))tools.unshift(x);});drawFilters();drawCatalog();
if(!tools.some(t=>t[0]==='Çatı'))tools.unshift(['Çatı','Çatı','m²',1250,410,'Kaplama, yalıtım ve mahya.']);drawFilters();drawCatalog();
const eskiAracAc=openTool;
toolRows=function(tool){const m=ortakModel(tool);return m.items.map(x=>({ad:x[0],birim:x[1],tur:x[4],oran:x[2],fiyat:x[3]}));};
openTool=function(i){eskiAracAc(i);const tool=tools[i],model=ortakModel(tool),waste=$('#standaloneWaste'),extra=$('.extra-grid');extra.innerHTML=model.extras.map(x=>`<label>${x[0]}${x[1]==='select'?`<select>${x[2].split('|').map(v=>`<option>${v}</option>`).join('')}</select>`:`<input type="${x[1]}" value="${x[2]}">`}</label>`).join('');waste.value=model.waste;const fix=()=>{const area=+$('#standaloneArea').value||0,fire=1+(+waste.value||0)/100,mode=$('#standaloneMode').value,vatOn=$('#standaloneVat').checked;let material=0,labor=0,other=0;const result=model.items.map((item,n)=>{const entered=+($(`#standalonePrice-${n}`)?.value),price=mode==='quantity'?0:mode==='official'?item[3]:(Number.isFinite(entered)?entered:item[3]),amount=item[4]==='Diğer'?1:item[2]*area*fire,total=amount*price;if(item[4]==='Malzeme')material+=total;else if(item[4]==='İşçilik')labor+=total;else other+=total;return {item,price,amount,total};});const subtotal=material+labor+other,vat=vatOn?subtotal*.2:0;$('#standaloneMaterial').textContent=mode==='quantity'?'—':money(material);$('#standaloneLabor').textContent=mode==='quantity'?'—':money(labor);$('#standaloneOther').textContent=mode==='quantity'?'—':money(other);$('#standaloneVatTotal').textContent=mode==='quantity'?'—':money(vat);$('#standaloneTotal').textContent=mode==='quantity'?'Fiyatsız metraj':money(subtotal+vat);$('#standaloneAssumption').textContent=`${area} ${tool[2]} net ölçü · %${waste.value} fire · ${mode==='custom'?'kullanıcı fiyatları':mode==='quantity'?'metraj modu':'varsayılan fiyat modu'}`;$('#standaloneChart').innerHTML=[['Malzeme',material],['İşçilik',labor],['Diğer',other]].map(x=>`<div><span>${x[0]}</span><i><b style="width:${subtotal?x[1]/subtotal*100:0}%"></b></i><strong>${mode==='quantity'?'—':money(x[1])}</strong></div>`).join('');$('#standaloneShopping').innerHTML=result.filter(x=>x.item[4]==='Malzeme').map(x=>`<p><b>${x.item[0]}<small>${x.item[1]} · fire dahil</small></b><span>${x.amount.toLocaleString('tr-TR',{maximumFractionDigits:2})} ${x.item[1]}</span></p>`).join('');};window.prokontStandaloneFix=fix;fix();};

/* Fiyat satırları mod değişince yeniden üretildiği için olayı kapsayıcıdan dinliyoruz. */
document.addEventListener('input',event=>{if(event.target.id?.startsWith('standalone'))window.prokontStandaloneFix?.();});
document.addEventListener('change',event=>{if(event.target.id?.startsWith('standalone'))window.prokontStandaloneFix?.();});
